import React from "react";
import { useOktaAuth } from "@okta/okta-react";
import { jwtDecode } from "jwt-decode";

const Profile = () => {
  const { authState } = useOktaAuth();

  if (!authState?.isAuthenticated) return null;

  const idToken = authState.idToken?.idToken;
  const decoded = jwtDecode(idToken);

  // ✅ Get actual firstName and lastName from Okta claims
  const firstName = decoded.firstName || "User";
  const lastName = decoded.lastName || "";

  // ✅ Get role from custom claim (e.g., "roles")
  const role =
    decoded.roles && decoded.roles.length > 0
      ? decoded.roles[0]
      : "User";

  return (
    <li className="nav-item nav-profile">
      <a href="#" className="nav-link">
        <div className="profile-image">
          <img
            className="img-xs rounded-circle"
            src="/images/faces/face8.jpg"
            alt="profile"
          />
          <div className="dot-indicator bg-success"></div>
        </div>
        <div className="text-wrapper">
          <p className="profile-name">{firstName} {lastName}</p>
          <p className="designation">
            {role.charAt(0).toUpperCase() + role.slice(1)}
          </p>
        </div>
        <div className="icon-container">
          <i className="icon-bubbles"></i>
          <div className="dot-indicator bg-danger"></div>
        </div>
      </a>
    </li>
  );
};

export default Profile;
